// satellites-score.js: THE SOUNDTRACK'S SCORE for the twelve satellites, written by tools/satellites-score.mjs (do not edit by hand; run it again).
// Measured off saint-seiya.m4a, frames 3825 to 3881 cut out of the uncut film's measure: one byte a film frame (30000/1001 a second) for each value, 0 to 255 standing for 0 to 1 (the tool's header says how):
// level (loudness), bass (20 to 150 Hz), voice (the speech band over its bed), beat (onset strength), energy (the slow rising curve),
// said (the spoken line's weight while it lasts); and lines, [[t0, t1, weight]] in the film's seconds, from the burned-in subtitles (tools/film-lines.swift; the words are not kept). 4568 frames, 152.409 s.
// scoreAt(seconds) -> {level, bass, voice, beat, energy, said} each 0 to 1, interpolated between frames; 0 outside the film. Pure, no state.

const B64 = {
  level: '',
  bass: '',
  voice: '',
  beat: '',
  energy: '',
  said: '',
};
const decode = (s) => { const t = atob(s), out = new Uint8Array(t.length); for (let i = 0; i < t.length; i++) out[i] = t.charCodeAt(i); return out; };
export const SCORE = Object.freeze({fps: 30000 / 1001, frames: 4568, seconds: 152.409, lineSource: 'subtitles', names: Object.freeze(["level","bass","voice","beat","energy","said"]),
  values: Object.freeze(Object.fromEntries(Object.entries(B64).map(([k, s]) => [k, decode(s)]))),
  lines: Object.freeze([[0.5,2.5,0.344],[3.5,4.5,0.328],[12.5,13.5,0.663],[14.5,16.5,0.396],[19.5,20.5,0.634],[24.5,28.5,0.631],[30.5,32.5,0.356],[33.5,35.5,0.307],[78.5,82.75,0.365],[82.75,84.75,0.655],[84.75,85.5,0.388],[85.5,85.75,0.645],[85.75,86.5,0.664],[86.5,86.75,0.411],[86.75,87.5,0.407],[100.5,103.5,0.638],[104.5,106.5,0.654],[124.5,127.25,0.605],[127.25,127.5,0.631]].map((l) => Object.freeze(l)))});
/** The score at the film's second: each value 0 to 1, read between the two frames around it. */
export function scoreAt(seconds) {
  const out = {level: 0, bass: 0, voice: 0, beat: 0, energy: 0, said: 0};
  if (!Number.isFinite(seconds) || seconds < 0) return out;
  const f = seconds * SCORE.fps, i = Math.floor(f), k = f - i;
  if (i >= SCORE.frames) return out;
  for (const name of SCORE.names) { const v = SCORE.values[name], a = v[i], b = i + 1 < SCORE.frames ? v[i + 1] : a; out[name] = (a + (b - a) * k) / 255; }
  return out;
}
